#! /usr/bin/python3
#
# Creates MinGW import libraries for the imports used by assembler file generated by SRW64.
#
# SRW64 writes every used import as "extern Name ; dll.dll" (or "extern __imp_Name ; dll.dll"),
# imports by ordinal (without known name) as "extern Name ; dll.dll ordinal N".
#
# usage: python3 mkimplibs.py <file.asm> <output directory> [dlltool]
# prints list of created libraries (to be passed to the linker)
#

import os
import re
import subprocess
import sys

asm_name = sys.argv[1]
output_dir = sys.argv[2]
dlltool = sys.argv[3] if len(sys.argv) > 3 else 'x86_64-w64-mingw32-dlltool'

dlls = {}
with open(asm_name, 'rt') as asm_file:
    for line in asm_file:
        match = re.match(r'extern (\S+) ; (\S+)(?: ordinal (\d+))?', line)
        if not match:
            continue
        name, dll, ordinal = match.group(1), match.group(2), match.group(3)
        if name.startswith('__imp_'):
            name = name[6:]
        dlls.setdefault(dll, set()).add((name, ordinal))

libraries = []
for dll, names in sorted(dlls.items()):
    base = re.sub(r'[^A-Za-z0-9_]', '_', os.path.splitext(dll)[0].lower())
    def_name = os.path.join(output_dir, base + '.def')
    with open(def_name, 'wt') as def_file:
        def_file.write('LIBRARY "%s"\nEXPORTS\n' % dll)
        for name, ordinal in sorted(names, key=lambda item: (item[0], item[1] or '')):
            if ordinal:
                def_file.write('    "%s" @%s NONAME\n' % (name, ordinal))
            else:
                def_file.write('    "%s"\n' % name)
    library = os.path.join(output_dir, 'lib%s_srw64.a' % base)
    subprocess.run([dlltool, '-d', def_name, '-l', library], check=True)
    libraries.append(library)

print(' '.join(libraries))
